\label{def_classical}
Let $T\in (0,+\infty) \cup \{+\infty\}$. A function $z: [0,1]\times [0,T)\to \mathbb{R}$ is said to be a classical solution to $\Sigma$ on $[0,T)$ if: 
\begin{itemize}
    \item $z\in \mathscr{H}_{loc}^{2+\beta, 1+\beta/2}([0,1]\times [0,T))$ for some $\beta \in (0,1)$.
    \item \eqref{sigma_1_z} holds for all $(x,t) \in (0,1)\times (0,T)$. 
    \item \eqref{sigma_21} holds for all $t\in [0,T)$. 
    \item \eqref{sigma_3_z} holds for all $x\in [0,1]$.
\end{itemize}
A forward-complete classical solution to $\Sigma$ is any classical solution to $\Sigma$ on $[0,+\infty)$.
\hfill $\bullet$

\label{ass_1}
$\Psi \in \mathscr{C}^3(\mathbb{R})$, and there exists a constant $\mu$ satisfying
    $$\Psi' \geq \mu > 0. $$

\label{ass_o}
    There exists $\beta \in (0,1)$ such that
    $z_o\in \mathscr{H}^{2+\beta}([0,1])$. Furthermore, $$\Psi(z_o)_x\big|_{x=0}=\Psi(z_o)_x\big|_{x=1}=0.$$

\label{ass_3}
$\hat{z}_o\in \mathscr{H}^{2+\beta}([0,1])$ where $\beta$ is the same as in Assumption \ref{ass_o}, and
\begin{align*}
\Psi(\hat{z}_o)_x\big|_{x=0} = 0, \ \ \Psi(\hat{z}_o)_x\big|_{x=1} = k\left(\Psi(y(0))-\Psi(\hat{y}(0))\right). 
\end{align*}

\label{thm1}
Consider the systems $\Sigma$ and $\hat{\Sigma}$ with $k>0$ and observer gain, and let Assumption \ref{ass_1} hold. Then, for any initial conditions $z_o$ and $\hat{z}_o$ satisfying the regularity and compatibility conditions in Assumptions \ref{ass_o} and \ref{ass_3}, the estimation error $e=z-\hat{z}$, that is the unique forward-complete classical solution to $\Sigma_e$, satisfies, for all $t\geq 0$, 
\begin{align}
\intop_0^1 |e(x,t)| dx \leq \min \left\{1,C_1 \exp\left(-\lambda \mu t\right)\right\} \intop_0^1|e_o(x)|dx, \label{stab_ineq}
\end{align}
where 
\begin{align*}
\lambda &:= \xi^2, \\
C_1 &:= \sqrt{\exp(1)\left(\xi^2+\xi\cot(\xi)\right)},
\end{align*}
with $\xi$ the unique solution in $(0,\pi/2)$ to 
$$\xi \tan(\xi) = k.$$
\hfill $\square$

\label{rem1}
Since $\xi \in (0,\pi/2)$, then $\lambda \in (0,\pi^2/4)$. To determine the range of $C_1$, we analyze the variations of the function $f(\xi) := \xi \cot(\xi) + \xi^2$ on $(0,\pi/2)$. Using $\frac{d}{d\xi}\cot(\xi) = -\left(1+\cot^2(\xi)\right)$, we have
$f'(\xi) = \cot(\xi)+\xi-\xi\cot^2(\xi)$, so that, multiplying by $\sin^2(\xi)>0$,
\begin{align*}
\sin^2(\xi)f'(\xi) &= \sin(\xi)\cos(\xi) + \xi \left(\sin^2(\xi)-\cos^2(\xi)\right) \\
&= \frac{1}{2}\sin(2\xi)-\xi\cos(2\xi)=: g(\xi).
\end{align*}
Since $g(0)=0$ and $g'(\xi) = 2\xi\sin(2\xi)>0$ for all $\xi \in (0,\pi/2)$, we have $g>0$,
hence $f'>0$ on $(0,\pi/2)$. As $\lim_{\xi\to 0^+}\xi\cot(\xi)=1$ and $\cot(\pi/2)=0$, it
follows that $1<f(\xi)<\pi^2/4$ on $(0,\pi/2)$. Consequently,
\begin{align*}
C_1 \in \left(\exp\left(\frac{1}{2}\right),\exp\left(\frac{1}{2}\right)\frac{\pi}{2}\right).
\end{align*}
\hfill $\bullet$

\label{lem1}
Define the function 
\begin{align*}
\theta(x,t) := \intop_0^1\Psi'\left(\hat{z}(x,t)+\tau e(x,t)\right)d\tau \geq \mu. 
\end{align*}
Then, 
\begin{align*}
w = \theta e.
\end{align*}
In particular, 
\begin{align*}
\mathop{\mathrm{sign}}\nolimits(w) = \mathop{\mathrm{sign}}\nolimits(e).
\end{align*}

\label{lem2}
It holds that 
\begin{align}
\dot{V}(t) = -\intop_0^1\theta (x,t) e(x,t)^2 dx \leq - \mu \intop_0^1 e(x,t)^2 dx. \label{V_dot}
\end{align}

Differentiating $V$ in time, note that we have 
\begin{align*}
\dot{V}(t) =&~ \intop_0^1E(x,t) E_t(x,t) dx + \frac{1}{k}E(1,t)E_t(1,t) \\
=&~ \intop_0^1 E(x,t)\left(\intop_0^xe_t(y,t)dy \right)dx + \frac{1}{k}E(1,t)\intop_0^1e_t(y,t)dy \\
=&~\intop_0^1 E(x,t)\left(\intop_0^xw_{yy}(y,t)dy \right)dx + \frac{1}{k}E(1,t)\intop_0^1w_{yy}(y,t)dy.
\end{align*}
Applying integration by parts and using the boundary conditions $w_x(0,t)=E(0,t)=0$ and $w_x(1,t) = - k w(1,t)$, we obtain 
\begin{align*}
\dot{V}(t) =&~ \intop_0^1 E(x,t)w_x(x,t)dx + \frac{1}{k}E(1,t) w_x(1,t) \\
=&~ E(1,t)w(1,t) - E(1,t)w(1,t) - \intop_0^1E_x(x,t)w(x,t)dx \\
=&~ -\intop_0^1 e(x,t)w(x,t)dx.
\end{align*}
Using $w=\theta e$ from Lemma \ref{lem1}, we have $we=\theta e^2$. Hence,
\begin{align*}
\dot{V}(t) = -\intop_0^1 \theta(x,t) e(x,t)^2 dx. 
\end{align*}
Finally, using $\theta \geq \mu$ from Lemma \ref{lem1}, we obtain \eqref{V_dot}.

\label{lem3}
Let $k>0$ and $\lambda$ be as in Theorem \ref{thm1}. For every $\phi \in \mathscr{C}^1([0,1])$
with $\phi(0)=0$,
\begin{align}\label{eq_poincare}
\intop_0^1 \phi(x)^2dx + \frac{\phi(1)^2}{k} \leq \frac{1}{\lambda}\intop_0^1 \phi'(x)^2dx .
\end{align}

\label{lem4}
For all $t\geq 0$, it holds that 
\begin{align}
2V(t) \leq \frac{1}{\lambda}\intop_0^1e(x,t)^2dx. \label{V_bound}
\end{align}

Since $E(\cdot,t)\in \mathscr{C}^1([0,1])$ and $E(0,t)=0$ for each $t\geq 0$, we can apply Lemma \ref{lem3} with $\phi$ therein replaced by $E(\cdot,t)$, to obtain 
\begin{align*}
\intop_0^1E(x,t)^2dx + \frac{E(1,t)^2}{k} \leq \frac{1}{\lambda}\intop_0^1e(x,t)^2dx.
\end{align*}

\label{lem5}
For all $t\geq 0$, we have  
\begin{align}
V(t) &\leq \exp\left(-2\lambda \mu t\right)V(0), \label{first_ineq} \\
\intop_t^{+\infty}\intop_0^1e(x,s)^2dx ds &\leq \frac{1}{\mu}\exp(-2\lambda \mu t)V(0). \label{second_ineq}
\end{align}

Using \eqref{V_dot} and \eqref{V_bound}, we have 
\begin{align*}
\dot{V}(t) \leq -2\lambda \mu V(t),
\end{align*}
which implies \eqref{first_ineq} by Grönwall's inequality. Furthermore, from \eqref{V_dot}, note that we have 
\begin{align}
\intop_0^1e(x,t)^2dx \leq -\frac{1}{\mu}\dot{V}(t). \label{to_int}
\end{align}
Integrating both sides of \eqref{to_int} with respect to time and using \eqref{first_ineq} and the fact that $V(t) \to 0$ as $t\to +\infty$, we find
\begin{align*}
\intop_t^{+\infty}\intop_0^1e(x,s)^2dx ds &\leq \frac{1}{\mu} V(t) \nonumber \\
&\leq \frac{1}{\mu}\exp(-2\lambda \mu t) V(0).
\end{align*}

\label{lem6}
Let $\varepsilon >0$ and $\varphi_{\varepsilon} \in \mathscr{C}^{\infty}(\mathbb{R};\mathbb{R}_{\geq 0})$ be given by 
\begin{align}
\varphi_{\varepsilon}(s) := \sqrt{s^2+\varepsilon^2} - \varepsilon \quad \forall s\in \mathbb{R}. 
\end{align}
Then, the following properties hold. 
\begin{itemize}
    \item[(i)] For all $s\in \mathbb{R}$, we have
    \begin{align*}
    0 \leq |s| - \varphi_{\varepsilon}(s) \leq \varepsilon
    \end{align*}
    \item[(ii)] For all $s \in \mathbb{R}$, we have $|\varphi_{\varepsilon}'(s)| \leq 1$ and 
    \begin{align*}
        \lim_{\varepsilon \to 0}\varphi_{\varepsilon}'(s) = \mathop{\mathrm{sign}}\nolimits(s). 
    \end{align*}
    \item[(iii)] For all $s\in \mathbb{R}$, we have $\varphi''_{\varepsilon}(s) >0$.
\end{itemize}

To prove (i), first note that 
\begin{align*}
s^2 \leq s^2 + \varepsilon^2 \leq \left(|s|+\varepsilon\right)^2.
\end{align*}
Hence, 
\begin{align*}
|s| \leq \sqrt{s^2+\varepsilon^2} \leq |s| + \varepsilon. 
\end{align*}
As a consequence, on the one hand, we have 
\begin{align*}
0\leq |s| - \left(\sqrt{s^2+\varepsilon^2} - \varepsilon\right) = |s| - \varphi_{\varepsilon}(s).
\end{align*}
On the other hand, we have 
\begin{align*}
|s|- \sqrt{s^2+\varepsilon^2} \leq 0,
\end{align*}
which implies that 
\begin{align*}
|s|-\varphi_{\varepsilon}(s) = |s| - \left(\sqrt{s^2+\varepsilon^2} - \varepsilon\right) \leq \varepsilon.
\end{align*}

Next, to prove (ii), note that 
\begin{align*}
\varphi_{\varepsilon}'(s) = \frac{s}{\sqrt{s^2+\varepsilon^2}}. 
\end{align*}
It implies that $|\varphi_{\varepsilon}'(s)| \leq 1$, and, for $s\not\nobreak\mkern -2mu = 0$,
\begin{align*}
\lim_{\varepsilon \to 0} \varphi'_{\varepsilon}(s) = \frac{s}{|s|} = \mathop{\mathrm{sign}}\nolimits(s). 
\end{align*}
When $s=0$, we have $\varphi_{\varepsilon}'(s) = \varphi'_{\varepsilon}(0) = 0 = \mathop{\mathrm{sign}}\nolimits(0) = \mathop{\mathrm{sign}}\nolimits(s)$. 

Finally, to prove (iii), it is sufficient to note that 
\begin{align*}
\varphi_{\varepsilon}''(s) = \frac{\varepsilon^2}{(s^2+\varepsilon^2)^{3/2}} >0.
\end{align*}

\label{lem7}
For all $t_1,t_2\in \mathbb{R}_{\geq 0}$ with $t_1\leq t_2$, we have 
\begin{align}
\intop_0^1|e(x,t_2)|dx \leq \intop_0^1|e(x,t_1)|dx - k\intop_{t_1}^{t_2}|w(1,t)|dt. \label{stab_L1}
\end{align}

Let $\varepsilon>0$ and $\varphi_{\varepsilon}$ be defined in Lemma \ref{lem6}. Moreover, let
\begin{align*}
L_{\varepsilon}(t) := \intop_0^1 \varphi_{\varepsilon}\left(e(x,t)\right)dx \quad \forall t\geq 0. 
\end{align*}
Using (i) in Lemma \ref{lem6}, note that we have, for all $t\geq 0$, 
\begin{align*}
0 \leq L_{\varepsilon}(t) - \intop_0^1 |e(x,t)|dx \leq \varepsilon.
\end{align*}
Hence, $L_\varepsilon(t) \to \intop_0^1|e(x,t)|dx$ as $\varepsilon \to 0$, uniformly in $t$. Consequently, to establish \eqref{stab_L1}, we first analyze $L_\varepsilon$ and then we pass to the limit as $\varepsilon\to0$. 

Differentiating $L_{\varepsilon}$ with respect to time and using $\Sigma_e$, we obtain 
\begin{align*}
\dot{L}_{\varepsilon}(t) =&~ \intop_0^1 \varphi_{\varepsilon}'(e(x,t))e_t(x,t)dx \\
=&~ \intop_0^1 \varphi_{\varepsilon}'(e(x,t))w_{xx}(x,t)dx. 
\end{align*}
We rewrite the latter identity as 
\begin{align*}
\dot{L}_{\varepsilon}(t)  =&~ \intop_0^1\varphi_{\varepsilon}'(w(x,t))w_{xx}(x,t)dx + \intop_0^1\left(\varphi_{\varepsilon}'(e(x,t))-\varphi_{\varepsilon}'(w(x,t))\right)w_{xx}(x,t)dx. 
\end{align*}
Applying integration by parts, and using $w_x(1,t)=-kw(1,t)$, $w_x(0,t)=0$, and (iii), we obtain 
\begin{align*}
\intop_0^1 \varphi_{\varepsilon}'(w(x,t))w_{xx}(x,t)dx =&~ \left[\varphi_{\varepsilon}'(w(x,t))w_{x}(x,t)\right]_{x=0}^{x=1} - \intop_0^1 \varphi_{\varepsilon}''(w(x,t))w_{x}(x,t)^2 dx \\
\leq&~ - k\varphi_{\varepsilon}'(w(1,t))w(1,t).
\end{align*}
As a result, we have 
\begin{align*}
\dot{L}_{\varepsilon}(t) \leq&~ - k\varphi_{\varepsilon}'(w(1,t))w(1,t) +\intop_0^1\left(\varphi_{\varepsilon}'(e(x,t))-\varphi_{\varepsilon}'(w(x,t))\right)w_{xx}(x,t)dx.
\end{align*}
Integrating in time from $t_1$ to $t_2$, we find 
\begin{align*}
L_{\varepsilon}(t_2) \leq&~ L_{\varepsilon}(t_1) - k\intop_{t_1}^{t_2}\varphi_{\varepsilon}'(w(1,t))w(1,t)dt + \intop_{t_1}^{t_2}\intop_0^1\left(\varphi_{\varepsilon}'(e(x,t))-\varphi_{\varepsilon}'(w(x,t))\right)w_{xx}(x,t)dxdt. 
\end{align*}
We will now pass to the limit as $\varepsilon \to 0$. We have already shown that $L_{\varepsilon}(t) \to \intop_{0}^1|e(x,t)|dx$ as $\varepsilon \to 0$, for all $t\geq 0$. Furthermore, from (ii) in Lemma \ref{lem6}, the fact that $t\mapsto w(1,t)$ is continuous hence bounded on the compact interval $[t_1,t_2]$, and the Lebesgue dominated convergence theorem, we have 
\begin{align*}
\intop_{t_1}^{t_2}\varphi_{\varepsilon}'(w(1,t))w(1,t)dt  \to \intop_{t_1}^{t_2}|w(1,t)|dt \ \ \text{as} \ \ \varepsilon \to 0. 
\end{align*}
Similarly, 
\begin{align*}
&\intop_{t_1}^{t_2}\intop_0^1\left(\varphi_{\varepsilon}'(e(x,t))-\varphi_{\varepsilon}'(w(x,t))\right)w_{xx}(x,t)dxdt \to \intop_{t_1}^{t_2}\intop_0^1\left(\mathop{\mathrm{sign}}\nolimits(e(x,t))-\mathop{\mathrm{sign}}\nolimits(w(x,t))\right)w_{xx}(x,t)dxdt
\end{align*}
as $\varepsilon \to 0$. However, from Lemma \ref{lem1}, we have $\mathop{\mathrm{sign}}\nolimits(e)=\mathop{\mathrm{sign}}\nolimits(w)$. Hence, 
\begin{align*}
\intop_{t_1}^{t_2}\intop_0^1\left(\varphi_{\varepsilon}'(e(x,t))-\varphi_{\varepsilon}'(w(x,t))\right)w_{xx}(x,t)dxdt \to 0
\end{align*}
as $\varepsilon \to 0$, which concludes the proof.
